import axios from 'axios';

/**
 * BreezeService - Service for interacting with the ICICI Direct Breeze API
 * This service provides methods to initialize the connection, 
 * look up stock codes, and retrieve historical price data
 */
class BreezeService {
  constructor() {
    this.isInitialized = false;
    this.breeze = null;
    this.apiKey = '';
    this.apiSecret = '';
    this.sessionKey = '';
    this.stockMapping = {}; // Cache for ICICI stock code -> NSE ticker
  }

  /**
   * Initialize the Breeze API connection with credentials
   * @param {Object} credentials - The API credentials
   * @param {string} credentials.apiKey - The Breeze API key
   * @param {string} credentials.apiSecret - The Breeze API secret
   * @param {string} credentials.sessionKey - The Breeze API session key
   * @returns {Promise<boolean>} - Whether initialization was successful
   */
  async initialize(credentials) {
    try {
      console.log('Initializing Breeze API connection...');

      // For production code, this would use the actual breezeconnect library
      // import BreezeConnect from 'breezeconnect';
      // this.breeze = new BreezeConnect({appKey: credentials.apiKey});

      // Store credentials
      this.apiKey = credentials.apiKey;
      this.apiSecret = credentials.apiSecret;
      this.sessionKey = credentials.sessionKey;

      // For the demo, we'll simulate the initialization
      await new Promise(resolve => setTimeout(resolve, 500)); // Simulate API call

      this.isInitialized = true;
      console.log('Breeze API initialized successfully');
      return true;
    } catch (error) {
      console.error('Failed to initialize Breeze API:', error);
      this.isInitialized = false;
      throw new Error(`Failed to initialize Breeze API: ${error.message}`);
    }
  }

  /**
   * Check if the service is initialized
   * @returns {boolean} - Whether the service is initialized
   */
  isReady() {
    return this.isInitialized;
  }

  /**
   * Get credentials from local storage or environment
   * @returns {Object} - The stored credentials or empty object
   */
  getStoredCredentials() {
    try {
      const storedCreds = localStorage.getItem('breezeCredentials');
      return storedCreds ? JSON.parse(storedCreds) : {};
    } catch (error) {
      console.error('Error retrieving stored credentials:', error);
      return {};
    }
  }

  /**
   * Save credentials to local storage
   * @param {Object} credentials - The credentials to store
   */
  saveCredentials(credentials) {
    try {
      localStorage.setItem('breezeCredentials', JSON.stringify(credentials));
    } catch (error) {
      console.error('Error saving credentials:', error);
    }
  }

  /**
   * Clear stored credentials
   */
  clearCredentials() {
    try {
      localStorage.removeItem('breezeCredentials');
    } catch (error) {
      console.error('Error clearing credentials:', error);
    }
  }

  /**
   * Look up an ICICI Direct stock code and convert to NSE ticker
   * @param {string} stockCode - The ICICI Direct stock code
   * @returns {Promise<string>} - The corresponding NSE ticker
   */
  async lookupStock(stockCode) {
    if (!this.isInitialized) {
      throw new Error('Breeze API not initialized');
    }

    // Check cache first
    if (this.stockMapping[stockCode]) {
      return this.stockMapping[stockCode];
    }

    try {
      // In production, this would call the actual Breeze API
      // const stockInfo = await this.breeze.getNames({
      //   exchangeCode: 'NSE',
      //   stockCode: stockCode
      // });

      // For the demo, we'll simulate the lookup with some common mappings
      await new Promise(resolve => setTimeout(resolve, 300)); // Simulate API call

      // Hard-coded mappings for demo purposes
      const demoMappings = {
        'RELIANCE': 'RELIANCE.NS',
        'TCS': 'TCS.NS',
        'INFY': 'INFY.NS',
        'HDFCBANK': 'HDFCBANK.NS',
        'ICICIBANK': 'ICICIBANK.NS',
        'ITC': 'ITC.NS',
        'TATASTEEL': 'TATASTEEL.NS',
        'AXISBANK': 'AXISBANK.NS',
        'WIPRO': 'WIPRO.NS',
        'NEULAB': 'NEULAB.NS',
        'KILIND': 'KILIND.NS'
      };

      const nseTicker = demoMappings[stockCode] || `${stockCode}.NS`;

      // Cache the mapping
      this.stockMapping[stockCode] = nseTicker;

      return nseTicker;
    } catch (error) {
      console.error(`Error looking up stock ${stockCode}:`, error);
      // Default to appending .NS as a fallback
      const fallbackTicker = `${stockCode}.NS`;
      this.stockMapping[stockCode] = fallbackTicker;
      return fallbackTicker;
    }
  }

  /**
   * Batch lookup multiple stock codes
   * @param {string[]} stockCodes - Array of ICICI Direct stock codes
   * @returns {Promise<Object>} - Map of stock codes to NSE tickers
   */
  async batchLookupStocks(stockCodes) {
    if (!this.isInitialized) {
      throw new Error('Breeze API not initialized');
    }

    const results = {};

    // Process in batches to avoid rate limiting
    for (const code of stockCodes) {
      try {
        results[code] = await this.lookupStock(code);
      } catch (error) {
        console.error(`Error in batch lookup for ${code}:`, error);
        results[code] = `${code}.NS`; // Default fallback
      }
    }

    return results;
  }

  /**
   * Get historical price data for a stock on a specific date
   * @param {string} stockCode - The ICICI Direct stock code
   * @param {string} date - The date in YYYY-MM-DD format
   * @returns {Promise<number>} - The closing price for that date
   */
  async getHistoricalPrice(stockCode, date) {
    if (!this.isInitialized) {
      throw new Error('Breeze API not initialized');
    }

    try {
      const nseTicker = await this.lookupStock(stockCode);

      // In production, this would call the actual Breeze API
      // const fromDate = new Date(date);
      // fromDate.setHours(0, 0, 0, 0);
      // 
      // const toDate = new Date(date);
      // toDate.setHours(23, 59, 59, 999);
      // 
      // const histData = await this.breeze.getHistoricalDatav2({
      //   interval: '1day',
      //   fromDate: fromDate.toISOString(),
      //   toDate: toDate.toISOString(),
      //   stockCode: stockCode,
      //   exchangeCode: 'NSE',
      //   productType: 'cash'
      // });

      // For the demo, we'll simulate historical prices
      await new Promise(resolve => setTimeout(resolve, 200)); // Simulate API call

      // Generate a semi-random but consistent price based on the stock code and date
      const seed = stockCode.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
      const dateSeed = new Date(date).getTime() / (1000 * 60 * 60 * 24);
      const basePrice = (seed % 1000) + 100; // Base price between 100 and 1100

      // Add some variation based on the date
      const variation = Math.sin(dateSeed / 10) * 0.15; // +/- 15%
      const price = basePrice * (1 + variation);

      return parseFloat(price.toFixed(2));
    } catch (error) {
      console.error(`Error getting historical price for ${stockCode} on ${date}:`, error);
      throw new Error(`Failed to get historical price: ${error.message}`);
    }
  }

  /**
   * Get historical prices for a stock over a date range
   * @param {string} stockCode - The ICICI Direct stock code
   * @param {string} startDate - Start date in YYYY-MM-DD format
   * @param {string} endDate - End date in YYYY-MM-DD format
   * @returns {Promise<Object>} - Map of dates to prices
   */
  async getHistoricalPrices(stockCode, startDate, endDate) {
    if (!this.isInitialized) {
      throw new Error('Breeze API not initialized');
    }

    try {
      const nseTicker = await this.lookupStock(stockCode);

      // In production, this would call the actual Breeze API
      // const histData = await this.breeze.getHistoricalDatav2({
      //   interval: '1day',
      //   fromDate: new Date(startDate).toISOString(),
      //   toDate: new Date(endDate).toISOString(),
      //   stockCode: stockCode,
      //   exchangeCode: 'NSE',
      //   productType: 'cash'
      // });

      // For the demo, we'll generate simulated prices for each day in the range
      const start = new Date(startDate);
      const end = new Date(endDate);
      const prices = {};

      // Generate days in the range
      const days = [];
      const currentDate = new Date(start);

      while (currentDate <= end) {
        const dateStr = currentDate.toISOString().split('T')[0];
        days.push(dateStr);
        currentDate.setDate(currentDate.getDate() + 1);
      }

      // Get price for each day
      for (const day of days) {
        prices[day] = await this.getHistoricalPrice(stockCode, day);
      }

      return prices;
    } catch (error) {
      console.error(`Error getting historical prices for ${stockCode}:`, error);
      throw new Error(`Failed to get historical prices: ${error.message}`);
    }
  }

  /**
   * Get real-time price for a stock
   * @param {string} stockCode - The ICICI Direct stock code
   * @returns {Promise<number>} - The current price
   */
  async getCurrentPrice(stockCode) {
    if (!this.isInitialized) {
      throw new Error('Breeze API not initialized');
    }

    try {
      const nseTicker = await this.lookupStock(stockCode);

      // In production, this would call the actual Breeze API
      // const quote = await this.breeze.getQuotes({
      //   stockCode: stockCode,
      //   exchangeCode: 'NSE',
      //   productType: 'cash'
      // });

      // For the demo, we'll simulate current prices
      await new Promise(resolve => setTimeout(resolve, 100)); // Simulate API call

      // Generate a semi-random price based on the stock code
      const seed = stockCode.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
      const basePrice = (seed % 1000) + 100; // Base price between 100 and 1100

      // Add a small random variation
      const variation = (Math.random() - 0.5) * 0.05; // +/- 2.5%
      const price = basePrice * (1 + variation);

      return parseFloat(price.toFixed(2));
    } catch (error) {
      console.error(`Error getting current price for ${stockCode}:`, error);
      throw new Error(`Failed to get current price: ${error.message}`);
    }
  }

  /**
   * Batch get current prices for multiple stocks
   * @param {string[]} stockCodes - Array of ICICI Direct stock codes
   * @returns {Promise<Object>} - Map of stock codes to current prices
   */
  async batchGetCurrentPrices(stockCodes) {
    if (!this.isInitialized) {
      throw new Error('Breeze API not initialized');
    }

    const results = {};

    // Process in batches to avoid rate limiting
    for (const code of stockCodes) {
      try {
        results[code] = await this.getCurrentPrice(code);
      } catch (error) {
        console.error(`Error getting price for ${code}:`, error);
        // Generate a fallback price
        const fallbackPrice = 100 + Math.random() * 900;
        results[code] = parseFloat(fallbackPrice.toFixed(2));
      }
    }

    return results;
  }
}

// Export a singleton instance
const breezeService = new BreezeService();
export default breezeService;
